package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type config struct {
	indent                  int
	inputFormat             string
	outputFormat            string
	nullInput               bool
	noDoc                   bool
	nulOutput               bool
	prettyPrint             bool
	inplace                 bool
	exitStatus              bool
	unwrapScalar            bool
	verbose                 bool
	expression              string
	fromFile                string
	securityDisableEnvOps   bool
	securityDisableFileOps  bool
	help                    bool
	version                 bool
}

type commandKind int

const (
	commandRoot commandKind = iota
	commandEval
	commandEvalAll
	commandCompletion
	commandHelp
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		io.WriteString(stdout, rootHelpShort)
		return 0
	}

	switch args[0] {
	case "help":
		return runHelp(args[1:], stdout)
	case "completion", "shell-completion":
		return runCommand(commandCompletion, true, args[1:], stdout, stderr)
	case "eval", "e":
		return runCommand(commandEval, true, args[1:], stdout, stderr)
	case "eval-all", "ea":
		return runCommand(commandEvalAll, true, args[1:], stdout, stderr)
	case "-h", "--help":
		if len(args) == 1 {
			io.WriteString(stdout, rootHelpLong)
			return 0
		}
	case "-V", "--version":
		if len(args) == 1 {
			io.WriteString(stdout, versionText)
			return 0
		}
	}

	return runCommand(commandEval, false, args, stdout, stderr)
}

func runHelp(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		io.WriteString(stdout, rootHelpLong)
		return 0
	}
	switch args[0] {
	case "eval", "e":
		io.WriteString(stdout, evalHelpLong)
	case "eval-all", "ea":
		io.WriteString(stdout, evalAllHelpLong)
	case "completion", "shell-completion":
		io.WriteString(stdout, completionHelpLong)
	default:
		io.WriteString(stdout, rootHelpLong)
	}
	return 0
}

func runCommand(kind commandKind, explicit bool, args []string, stdout, stderr io.Writer) int {
	cfg := config{
		indent:       2,
		inputFormat:  "auto",
		outputFormat: "auto",
		unwrapScalar: true,
	}
	positionals, err := parseFlags(&cfg, args)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %v\n", err)
		switch kind {
		case commandEval:
			if explicit {
				io.WriteString(stdout, evalHelpShort)
			} else {
				io.WriteString(stdout, rootHelpShort)
			}
		case commandEvalAll:
			io.WriteString(stdout, evalAllHelpLong)
		case commandCompletion:
			io.WriteString(stdout, completionHelpLong)
		}
		return 1
	}

	if cfg.version {
		io.WriteString(stdout, versionText)
		return 0
	}

	switch kind {
	case commandCompletion:
		if cfg.help {
			io.WriteString(stdout, completionHelpLong)
			return 0
		}
		return runCompletion(positionals, stdout)
	case commandEval:
		if explicit && cfg.help {
			io.WriteString(stdout, evalHelpLong)
			return 0
		}
		if !explicit && cfg.help {
			io.WriteString(stdout, rootHelpLong)
			return 0
		}
	case commandEvalAll:
		if cfg.help {
			io.WriteString(stdout, evalAllHelpLong)
			return 0
		}
	}

	exprText, files, err := resolveExpressionAndFiles(&cfg, positionals)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %v\n", err)
		return 1
	}

	if cfg.inplace && (exprText == "" || len(files) == 0) {
		fmt.Fprintln(stderr, "Error: write in place flag only applicable when giving an expression and at least one file")
		return 1
	}

	if exprText == "" && !cfg.nullInput && len(files) == 0 {
		if explicit {
			switch kind {
			case commandEval:
				io.WriteString(stdout, evalHelpShort)
			case commandEvalAll:
				io.WriteString(stdout, evalAllHelpLong)
			}
		} else {
			io.WriteString(stdout, rootHelpShort)
		}
		return 0
	}

	if exprText != "" && !cfg.nullInput && len(files) == 0 && !stdinAvailable() {
		io.WriteString(stdout, evalHelpShort)
		return 0
	}

	parsed, err := parseExpression(exprText)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %v\n", err)
		return 1
	}

	items, err := loadInputs(files, &cfg)
	if err != nil {
		fmt.Fprintf(stderr, "Error: %v\n", err)
		return 1
	}

	if cfg.nullInput {
		items = []evalItem{{Node: nil, FileIndex: 0, Format: "yaml"}}
	}
	if len(items) == 0 && exprText == "" {
		return 0
	}
	if len(items) == 0 && exprText != "" {
		items = []evalItem{{Node: nil, FileIndex: 0, Format: "yaml"}}
	}

	results := cloneItems(items)
	if parsed != nil {
		results, err = parsed.eval(results, &evalEnv{cfg: &cfg})
		if err != nil {
			fmt.Fprintf(stderr, "Error: %v\n", err)
			return 1
		}
	}

	if cfg.prettyPrint {
		for i := range results {
			clearStyles(results[i].Node)
		}
	}

	if cfg.inplace {
		data, err := renderOutputs(results, &cfg)
		if err != nil {
			fmt.Fprintf(stderr, "Error: %v\n", err)
			return 1
		}
		if err := os.WriteFile(files[0], data, 0o644); err != nil {
			fmt.Fprintf(stderr, "Error: %v\n", err)
			return 1
		}
	} else {
		data, err := renderOutputs(results, &cfg)
		if err != nil {
			fmt.Fprintf(stderr, "Error: %v\n", err)
			return 1
		}
		stdout.Write(data)
	}

	if cfg.exitStatus && !anyTruthy(results) {
		fmt.Fprintln(stderr, "Error: no matches found")
		return 1
	}
	return 0
}

func runCompletion(args []string, stdout io.Writer) int {
	if len(args) == 0 {
		io.WriteString(stdout, completionHelpLong)
		return 0
	}
	switch args[0] {
	case "bash":
		io.WriteString(stdout, "# bash completion for yq\n")
	case "zsh":
		io.WriteString(stdout, "#compdef yq\n")
	case "fish":
		io.WriteString(stdout, "complete -c yq\n")
	case "powershell":
		io.WriteString(stdout, "# powershell completion for yq\n")
	default:
		io.WriteString(stdout, completionHelpLong)
	}
	return 0
}

func parseFlags(cfg *config, args []string) ([]string, error) {
	positionals := make([]string, 0)
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			positionals = append(positionals, args[i+1:]...)
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			positionals = append(positionals, arg)
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name, value, hasValue := splitLongFlag(arg[2:])
			switch name {
			case "help":
				cfg.help = true
			case "version":
				cfg.version = true
			case "expression":
				v, err := requiredValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				cfg.expression = v
			case "from-file":
				v, err := requiredValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				cfg.fromFile = v
			case "input-format":
				v, err := requiredValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				cfg.inputFormat = v
			case "output-format":
				v, err := requiredValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				cfg.outputFormat = v
			case "indent":
				v, err := requiredValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				n, err := strconv.Atoi(v)
				if err != nil {
					return nil, err
				}
				cfg.indent = n
			case "front-matter", "csv-separator", "properties-separator", "shell-key-separator",
				"split-exp", "split-exp-file", "xml-attribute-prefix", "xml-content-name",
				"xml-directive-name", "xml-proc-inst-prefix", "lua-prefix", "lua-suffix":
				if _, err := requiredValue(args, &i, hasValue, value); err != nil {
					return nil, err
				}
			case "inplace":
				cfg.inplace = true
			case "null-input":
				cfg.nullInput = true
			case "no-doc":
				cfg.noDoc = true
			case "nul-output":
				cfg.nulOutput = true
			case "prettyPrint":
				cfg.prettyPrint = true
			case "exit-status":
				cfg.exitStatus = true
			case "verbose":
				cfg.verbose = true
			case "colors", "no-colors", "debug-node-info", "properties-array-brackets",
				"security-enable-system-operator", "header-preprocess", "string-interpolation",
				"csv-auto-parse", "tsv-auto-parse", "xml-keep-namespace", "xml-raw-token",
				"xml-skip-directives", "xml-skip-proc-inst", "xml-strict-mode", "lua-globals",
				"lua-unquoted", "yaml-compact-seq-indent", "yaml-fix-merge-anchor-to-spec":
				// accepted and ignored
			case "security-disable-env-ops":
				cfg.securityDisableEnvOps = true
			case "security-disable-file-ops":
				cfg.securityDisableFileOps = true
			case "unwrapScalar":
				v, ok, err := optionalBoolValue(args, &i, hasValue, value)
				if err != nil {
					return nil, err
				}
				if ok {
					cfg.unwrapScalar = v
				} else {
					cfg.unwrapScalar = true
				}
			default:
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			continue
		}
		if len(arg) < 2 {
			positionals = append(positionals, arg)
			continue
		}
		switch arg[1] {
		case 'h':
			cfg.help = true
		case 'V':
			cfg.version = true
		case 'e':
			cfg.exitStatus = true
		case 'n':
			cfg.nullInput = true
		case 'N':
			cfg.noDoc = true
		case '0':
			cfg.nulOutput = true
		case 'P':
			cfg.prettyPrint = true
		case 'i':
			cfg.inplace = true
		case 'v':
			cfg.verbose = true
		case 'C', 'M', 'c':
			// accepted and ignored
		case 'r':
			v, ok, err := shortOptionalBoolValue(arg[2:])
			if err != nil {
				return nil, err
			}
			if ok {
				cfg.unwrapScalar = v
			} else {
				cfg.unwrapScalar = true
			}
		case 'I':
			v, err := shortValue(args, &i, arg[2:])
			if err != nil {
				return nil, err
			}
			n, err := strconv.Atoi(v)
			if err != nil {
				return nil, err
			}
			cfg.indent = n
		case 'p':
			v, err := shortValue(args, &i, arg[2:])
			if err != nil {
				return nil, err
			}
			cfg.inputFormat = v
		case 'o':
			v, err := shortValue(args, &i, arg[2:])
			if err != nil {
				return nil, err
			}
			cfg.outputFormat = v
		case 'f':
			if _, err := shortValue(args, &i, arg[2:]); err != nil {
				return nil, err
			}
		case 's':
			if _, err := shortValue(args, &i, arg[2:]); err != nil {
				return nil, err
			}
		default:
			return nil, fmt.Errorf("unknown flag: %s", arg)
		}
	}
	return positionals, nil
}

func splitLongFlag(arg string) (string, string, bool) {
	if idx := strings.IndexByte(arg, '='); idx >= 0 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func requiredValue(args []string, i *int, hasValue bool, value string) (string, error) {
	if hasValue {
		return value, nil
	}
	if *i+1 >= len(args) {
		return "", fmt.Errorf("flag needs an argument")
	}
	*i++
	return args[*i], nil
}

func optionalBoolValue(args []string, i *int, hasValue bool, value string) (bool, bool, error) {
	if !hasValue {
		return false, false, nil
	}
	v, err := strconv.ParseBool(value)
	return v, true, err
}

func shortOptionalBoolValue(rest string) (bool, bool, error) {
	if rest == "" {
		return false, false, nil
	}
	if strings.HasPrefix(rest, "=") {
		v, err := strconv.ParseBool(rest[1:])
		return v, true, err
	}
	v, err := strconv.ParseBool(rest)
	return v, true, err
}

func shortValue(args []string, i *int, rest string) (string, error) {
	if rest != "" {
		if strings.HasPrefix(rest, "=") {
			return rest[1:], nil
		}
		return rest, nil
	}
	if *i+1 >= len(args) {
		return "", fmt.Errorf("flag needs an argument")
	}
	*i++
	return args[*i], nil
}

func resolveExpressionAndFiles(cfg *config, positionals []string) (string, []string, error) {
	exprText := cfg.expression
	if cfg.fromFile != "" {
		data, err := os.ReadFile(cfg.fromFile)
		if err != nil {
			return "", nil, err
		}
		exprText = strings.TrimRight(string(data), "\r\n")
	}
	if exprText != "" {
		return exprText, positionals, nil
	}
	if len(positionals) == 0 {
		return "", nil, nil
	}
	if allLookLikeFiles(positionals) {
		return "", positionals, nil
	}
	return positionals[0], positionals[1:], nil
}

func allLookLikeFiles(args []string) bool {
	for _, arg := range args {
		if arg == "-" {
			continue
		}
		if _, err := os.Stat(arg); err != nil {
			return false
		}
	}
	return true
}

func stdinAvailable() bool {
	info, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice == 0
}

func loadInputs(files []string, cfg *config) ([]evalItem, error) {
	var stdinData []byte
	if cfg.nullInput {
		return nil, nil
	}
	if len(files) == 0 {
		if !stdinAvailable() {
			return nil, nil
		}
		return loadOnePath("-", cfg.inputFormat, 0, &stdinData)
	}
	out := make([]evalItem, 0)
	for i, file := range files {
		items, err := loadOnePath(file, cfg.inputFormat, i, &stdinData)
		if err != nil {
			return nil, err
		}
		out = append(out, items...)
	}
	return out, nil
}

func clearStyles(node *yaml.Node) {
	if node == nil {
		return
	}
	node.Style = 0
	for _, child := range node.Content {
		clearStyles(child)
	}
}

func renderOutputs(items []evalItem, cfg *config) ([]byte, error) {
	var buf bytes.Buffer
	for i, item := range items {
		format := normalizeFormat(cfg.outputFormat)
		if format == "auto" {
			format = normalizeFormat(item.Format)
			if format == "auto" {
				format = "yaml"
			}
		}
		var data []byte
		var err error
		switch format {
		case "json":
			data, err = renderJSON(item.Node, cfg.indent)
		default:
			data, err = renderYAML(item.Node, cfg)
		}
		if err != nil {
			return nil, err
		}
		if i > 0 && format == "yaml" && !cfg.noDoc {
			buf.WriteString("---\n")
		}
		buf.Write(data)
	}
	return buf.Bytes(), nil
}

func renderYAML(node *yaml.Node, cfg *config) ([]byte, error) {
	if cfg.unwrapScalar && isScalarRenderable(node) {
		value := scalarString(node)
		if cfg.nulOutput {
			if strings.ContainsRune(value, 0) {
				return nil, fmt.Errorf("can't serialise value because it contains NUL char and you are using NUL separated output")
			}
			return append([]byte(value), 0), nil
		}
		return []byte(value + "\n"), nil
	}
	if node == nil {
		if cfg.nulOutput {
			return []byte{0}, nil
		}
		return []byte("\n"), nil
	}
	doc := yaml.Node{Kind: yaml.DocumentNode}
	if node != nil {
		doc.Content = []*yaml.Node{cloneNode(node)}
	}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(cfg.indent)
	if err := enc.Encode(&doc); err != nil {
		return nil, err
	}
	enc.Close()
	data := buf.Bytes()
	if cfg.nulOutput {
		data = bytes.TrimSuffix(data, []byte("\n"))
		data = append(data, 0)
	}
	return data, nil
}

func renderJSON(node *yaml.Node, indent int) ([]byte, error) {
	var buf bytes.Buffer
	if err := writeJSON(&buf, derefDocument(node), 0, indent); err != nil {
		return nil, err
	}
	buf.WriteByte('\n')
	return buf.Bytes(), nil
}

func writeJSON(w *bytes.Buffer, node *yaml.Node, depth int, indent int) error {
	if node == nil {
		w.WriteString("null")
		return nil
	}
	switch node.Kind {
	case yaml.MappingNode:
		w.WriteString("{")
		if len(node.Content) > 0 {
			w.WriteByte('\n')
		}
		for i := 0; i < len(node.Content); i += 2 {
			if i > 0 {
				w.WriteString(",\n")
			}
			writeIndent(w, depth+1, indent)
			key, _ := json.Marshal(node.Content[i].Value)
			w.Write(key)
			w.WriteString(": ")
			if err := writeJSON(w, node.Content[i+1], depth+1, indent); err != nil {
				return err
			}
		}
		if len(node.Content) > 0 {
			w.WriteByte('\n')
			writeIndent(w, depth, indent)
		}
		w.WriteString("}")
	case yaml.SequenceNode:
		w.WriteString("[")
		if len(node.Content) > 0 {
			w.WriteByte('\n')
		}
		for i, child := range node.Content {
			if i > 0 {
				w.WriteString(",\n")
			}
			writeIndent(w, depth+1, indent)
			if err := writeJSON(w, child, depth+1, indent); err != nil {
				return err
			}
		}
		if len(node.Content) > 0 {
			w.WriteByte('\n')
			writeIndent(w, depth, indent)
		}
		w.WriteString("]")
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			w.WriteString("null")
		case "!!bool", "!!int", "!!float":
			w.WriteString(node.Value)
		default:
			data, _ := json.Marshal(node.Value)
			w.Write(data)
		}
	default:
		w.WriteString("null")
	}
	return nil
}

func writeIndent(w *bytes.Buffer, depth int, indent int) {
	w.WriteString(strings.Repeat(" ", depth*indent))
}

func isScalarRenderable(node *yaml.Node) bool {
	node = derefDocument(node)
	return node != nil && node.Kind == yaml.ScalarNode
}

func scalarString(node *yaml.Node) string {
	node = derefDocument(node)
	if node == nil {
		return ""
	}
	return node.Value
}

